-    /* MASKED - implement this function */
+	struct log_cache_entry *entry;
+
+	/* Search active list for a matching entry */
+	SYS_SLIST_FOR_EACH_CONTAINER(&cache->active, entry, node) {
+		if (cache->cmp(entry->id, id)) {
+			cache->hit++;
+			*data = entry->data;
+			return true;
+		}
+	}
+
+	/* Miss */
+	cache->miss++;
+
+	if (!sys_slist_is_empty(&cache->idle)) {
+		entry = CONTAINER_OF(sys_slist_get(&cache->idle),
+				     struct log_cache_entry, node);
+	} else {
+		/* Evict the oldest (tail) entry from active list */
+		sys_snode_t *prev = NULL;
+		sys_snode_t *curr = sys_slist_peek_head(&cache->active);
+		sys_snode_t *next;
