+		while (curr != NULL) {
+			next = sys_slist_peek_next(curr);
+			if (next == NULL) {
+				break;
+			}
+			prev = curr;
+			curr = next;
+		}
+
+		entry = CONTAINER_OF(curr, struct log_cache_entry, node);
+		sys_slist_remove(&cache->active, prev, curr);
+	}
+
+	entry->id = id;
+	*data = entry->data;
+
+	return false;
 }

