+++ subsys/modem/modem_chat.c
@@ -852,7 +852,44 @@

 int modem_chat_run_script_async(struct modem_chat *chat, const struct modem_chat_script *script)
 {
-    /* MASKED - implement this function */
+	/* Validate arguments */
+	if ((chat == NULL) || (script == NULL)) {
+		return -EINVAL;
+	}
+
+	/* Validate script chats */
+	if (!modem_chat_validate_array(script->script_chats, script->script_chats_size)) {
+		return -EINVAL;
+	}
+
+	/* Validate abort matches */
+	if (!modem_chat_validate_array(script->abort_matches, script->abort_matches_size)) {
+		return -EINVAL;
+	}
+
+	/* Validate pipe is attached */
+	if (chat->pipe == NULL) {
+		return -EPERM;
+	}
+
+	/* Validate script is not already running */
+	if (atomic_test_bit(&chat->script_state, MODEM_CHAT_SCRIPT_STATE_RUNNING_BIT)) {
+		return -EBUSY;
+	}
+
+	/* Store pending script */
+	chat->pending_script = script;
+
+	/* Reset script stopped semaphore */
+	k_sem_reset(&chat->script_stopped_sem);
+
+	/* Set script running state */
+	atomic_set_bit(&chat->script_state, MODEM_CHAT_SCRIPT_STATE_RUNNING_BIT);
+
+	/* Submit script run work */
+	modem_work_submit(&chat->script_run_work);
+
+	return 0;
 }

