+		start = (state == ONOFF_STATE_OFF);
+		add_client = true;
+	} else if (state == ONOFF_STATE_RESETTING) {
+		rv = -ENOTSUP;
+	} else {
+		__ASSERT_NO_MSG(state == ONOFF_STATE_ERROR);
+		rv = -EIO;
+	}
+
+out:
+	if (add_client) {
+		sys_slist_append(&mgr->clients, &cli->node);
+	}
+
+	if (start) {
+		process_event(mgr, EVT_RECHECK, key);
