+	uint32_t sub_opt = options & (osFlagsWaitAll | osFlagsNoClear);
+	uint32_t sig;
+	unsigned int key;
+	int64_t remaining, end = 0;
+
+	if (k_is_in_isr()) {
+		return osFlagsErrorISR;
+	}
+
+	if ((flags == 0U) || (flags & osFlagsError)) {
+		return osFlagsErrorParameter;
+	}
+
+	tid = (struct cmsis_rtos_thread_cb *)osThreadGetId();
+	if (tid == NULL) {
+		return osFlagsErrorUnknown;
+	}
+
+	if (timeout != osWaitForever && timeout != 0U) {
+		end = k_uptime_ticks() + (int64_t)timeout;
+	}
+
+	for (;;) {
+		key = irq_lock();
+		sig = tid->signal_results;
+		irq_unlock(key);
