+		    ((sig & flags) == flags) : ((sig & flags) != 0)) {
+			if (!(sub_opt & osFlagsNoClear)) {
+				key = irq_lock();
+				tid->signal_results &= ~flags;
+				irq_unlock(key);
+			}
+			return sig;
+		}
+
+		if (timeout == 0U) {
+			return osFlagsErrorTimeout;
+		}
+
+		if (timeout == osWaitForever) {
+			if (k_poll(&tid->poll_event, 1, K_FOREVER) != 0) {
+				return osFlagsErrorTimeout;
+			}
+		} else {
+			remaining = end - k_uptime_ticks();
+			if (remaining <= 0) {
+				return osFlagsErrorTimeout;
+			}
+			if (k_poll(&tid->poll_event, 1,
+				   K_TICKS((uint32_t)remaining)) != 0) {
+				return osFlagsErrorTimeout;
+			}
+		}
+
+		key = irq_lock();
+		k_poll_signal_reset(&tid->poll_signal);
+		tid->poll_event.state = K_POLL_STATE_NOT_READY;
+		irq_unlock(key);
