+		set_child(succ, 0U, node_left);
+
+		if (node_right == succ) {
+			/* Successor is node's direct right child */
+			set_child(succ, 1U, node);
+		} else {
+			set_child(succ, 1U, node_right);
+			set_child(stack[stacksz - 2],
