patch:
--- lib/heap/heap.c
+++ lib/heap/heap.c
@@ -692,7 +692,59 @@
 void *sys_heap_aligned_realloc(struct sys_heap *heap, void *ptr,
 			       size_t align, size_t bytes)
 {
-    /* MASKED - implement this function */
+	/* Special realloc semantics: NULL ptr -> aligned_alloc, 0 bytes -> free */
+	if (ptr == NULL) {
+		return sys_heap_aligned_alloc(heap, align, bytes);
+	}
+	if (bytes == 0) {
+		sys_heap_free(heap, ptr);
+		return NULL;
+	}
+
+	struct z_heap *h = heap->heap;
+
+	/*
+	 * Decode alignment and rewind values, same as sys_heap_aligned_alloc().
+	 * align may encode a power-of-2 alignment plus one rewind bit
+	 * (e.g. 0x28 = align to 32, rewind 8).
+	 */
+	size_t rew = align & -align;
+	size_t effective_align;
+
+	if (align != rew) {
+		effective_align = align - rew;
+	} else {
+		effective_align = align;
+		rew = 0;
+	}
+	__ASSERT((effective_align & (effective_align - 1)) == 0,
+		 "align must be a power of 2");
+
+	/*
+	 * In-place expansion is attempted only if the existing pointer
+	 * conforms to the requested alignment.  When there is no rewind
+	 * and the effective alignment is no stricter than the heap's
+	 * natural alignment, any existing pointer satisfies it.
+	 * Otherwise we check explicitly.
+	 */
+	if ((rew == 0 && effective_align <= chunk_header_bytes(h)) ||
+	    (effective_align > 0 &&
+	     (((uintptr_t)ptr + rew) & (effective_align - 1)) == 0)) {
+		if (inplace_realloc(heap, ptr, bytes)) {
+			return ptr;
+		}
+	}
+
+	/* Fallback: allocate new aligned block, copy, and free old */
+	void *ptr2 = sys_heap_aligned_alloc(heap, align, bytes);
+
+	if (ptr2 != NULL) {
+		size_t prev_size = sys_heap_usable_size(heap, ptr);
+
+		memcpy(ptr2, ptr, min(prev_size, bytes));
+		sys_heap_free(heap, ptr);
+	}
+	return ptr2;
 }

