+	} else if (ret) {
+		goto detach;
+	}
+
+	ret = usb_dc_ep_enable(USB_CONTROL_EP_OUT);
+	if (ret == -EALREADY) {
+		LOG_WRN("EP 0x%02x already enabled", USB_CONTROL_EP_OUT);
+	} else if (ret) {
+		goto detach;
+	}
+
+	/* Configure and enable control endpoint IN */
+	ep_cfg.ep_addr = USB_CONTROL_EP_IN;
+
+	ret = usb_dc_ep_configure(&ep_cfg);
+	if (ret == -EALREADY) {
+		LOG_WRN("EP 0x%02x already configured", ep_cfg.ep_addr);
+	} else if (ret) {
+		goto detach;
+	}
+
+	ret = usb_dc_ep_enable(USB_CONTROL_EP_IN);
+	if (ret == -EALREADY) {
+		LOG_WRN("EP 0x%02x already enabled", USB_CONTROL_EP_IN);
+	} else if (ret) {
+		goto detach;
+	}
+
+	/* Install control transfer handler on EP0 */
+	ret = usb_dc_ep_set_callback(USB_CONTROL_EP_OUT,
+				     usb_handle_control_transfer);
+	if (ret) {
+		goto detach;
+	}
+
+	ret = usb_dc_ep_set_callback(USB_CONTROL_EP_IN,
+				     usb_handle_control_transfer);
+	if (ret) {
+		goto detach;
+	}
+
+	/* Install class endpoint callbacks */
+	ret = composite_setup_ep_cb();
+	if (ret) {
+		goto detach;
+	}
+
+	usb_dev.mps0 = USB_CONTROL_EP_MPS;
+	usb_dev.enabled = true;
+
+	k_mutex_unlock(&usb_enable_lock);
+
+	return 0;
+
+detach:
+	usb_dc_detach();
+unlock:
+	k_mutex_unlock(&usb_enable_lock);
+	return ret;
